    30	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
    31	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
    32	  ],
    33	  payments: [
    34	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
    35	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
    36	  ],
    37	};
